import * as fs from "node:fs/promises";
import * as path from "node:path";

// Native Windows always uses Bun: an unrelated sh.exe (including WSL) must not
// decide whether a Windows path can be launched. Re-apply refreshes this shim.
export const windowsShim = (cli: string, bun: string): string => {
	const quotePath = (p: string) => `"${p.replace(/\//g, "\\").replace(/%/g, "%%")}"`;
	return "@echo off\r\n" +
		"rem Generated by omp-zh. Runs the patched sidecar with Bun.\r\n" +
		"setlocal DisableDelayedExpansion\r\n" +
		`${quotePath(bun)} ${quotePath(cli)} %*\r\n` +
		"exit /b %ERRORLEVEL%\r\n";
};

/** Refresh only our generated CMD shims; preserve all unrelated files/links. */
export const linkLaunchers = async (
	launcher: string, cli: string, bun: string, dirs: readonly string[], windows: boolean,
): Promise<string[]> => {
	const linked: string[] = [];
	for (const dir of dirs) {
		const dest = path.join(dir, windows ? "omp-zh.cmd" : "omp-zh");
		try {
			await fs.mkdir(dir, { recursive: true });
			const existing = await fs.lstat(dest).catch(() => null);
			if (existing?.isSymbolicLink()) {
				const target = await fs.readlink(dest);
				if (path.resolve(dir, target) === path.resolve(launcher)) linked.push(dest);
				continue;
			}
			if (windows) {
				const current = existing?.isFile() ? await fs.readFile(dest, "utf8") : "";
				if (existing && !current.replace(/\r\n/g, "\n").startsWith("@echo off\nrem Generated by omp-zh.")) continue;
				const body = windowsShim(cli, bun);
				if (current !== body) await fs.writeFile(dest, body);
			} else {
				if (existing) continue;
				await fs.symlink(launcher, dest);
			}
			linked.push(dest);
		} catch { /* Report usable launchers only; another directory may still work. */ }
	}
	return linked;
};
